package keystrokesmod.script.packet.clientbound;
import java.util.ArrayList; import java.util.List; import keystrokesmod.script.model.Vec3; import net.minecraft.network.play.server.S27PacketExplosion;
public class S27 extends SPacket { public float strength; public Vec3 position,motion; public List<Vec3> affectedBlockPositions; public S27(S27PacketExplosion value){super(value);strength=value.getStrength();position=new Vec3(value.getX(),value.getY(),value.getZ());motion=new Vec3(0,0,0);affectedBlockPositions=new ArrayList<Vec3>();for(net.minecraft.util.BlockPos pos:value.getAffectedBlockPositions())affectedBlockPositions.add(new Vec3(pos));} public S27(float strength,Vec3 pos,Vec3 motion,List<Vec3> blocks){super(null);this.strength=strength;position=pos;this.motion=motion;affectedBlockPositions=blocks;} }
